#Dynamic_Waves {
    margin: auto;
    z-index: 1;
    min-height: 50vh;
    background: linear-gradient(315deg,
            rgba(101, 0, 94, 1) 3%,
            rgba(60, 132, 206, 1) 38%,
            rgba(48, 238, 226, 1) 68%,
            rgba(255, 255, 25, 1) 98%);
    animation: gradient 15s ease infinite;
    background-size: 400% 400%;
    background-attachment: fixed;
    width: 100%;
    height: 100%;
    position: relative;
    overflow: hidden;
}

#Dynamic_Waves .wave {
    background: rgb(255 255 255 / 25%);
    border-radius: 1000% 1000% 0 0;
    position: absolute;
    width: 200%;
    height: 192px;
    animation: wave 10s -3s linear infinite;
    transform: translate3d(0, 0, 0);
    opacity: 0.8;
    bottom: 0;
    left: 0;
    z-index: 2;
}

#Dynamic_Waves .wave:nth-of-type(2) {
    bottom: -20px;
    animation: wave 18s linear reverse infinite;
    opacity: 0.8;
}

#Dynamic_Waves .wave:nth-of-type(3) {
    bottom: -2.5em;
    animation: wave 20s -1s reverse infinite;
    opacity: 0.9;
}

#Dynamic_Waves h1 {
    position: absolute;
    top: 140px;
    color: white;
    font-family: cursive;
    text-align: center;
    width: 100%;
}

@keyframes gradient {
    0% {
        background-position: 0% 0%;
    }

    50% {
        background-position: 100% 100%;
    }

    100% {
        background-position: 0% 0%;
    }
}

@keyframes wave {
    2% {
        transform: translateX(1);
    }

    25% {
        transform: translateX(-25%);
    }

    50% {
        transform: translateX(-50%);
    }

    75% {
        transform: translateX(-25%);
    }

    100% {
        transform: translateX(1);
    }
}
